set -eo pipefail
git fetch {upstream_remote} {upstream_branch}
if git merge --no-edit {upstream_remote}/{upstream_branch}; then
  exit 0
fi
if ! git rev-parse -q --verify MERGE_HEAD >/dev/null; then
  exit 1
fi
git diff --name-only --diff-filter=U -z | while IFS= read -r -d '' f; do
  ours=$(mktemp)
  base=$(mktemp)
  theirs=$(mktemp)
  if git cat-file -e ":2:$f" 2>/dev/null; then git show ":2:$f" > "$ours"; else : > "$ours"; fi
  if git cat-file -e ":1:$f" 2>/dev/null; then git show ":1:$f" > "$base"; else : > "$base"; fi
  if git cat-file -e ":3:$f" 2>/dev/null; then git show ":3:$f" > "$theirs"; else : > "$theirs"; fi
  awk -v ours_file="$ours" -v base_file="$base" -v theirs_file="$theirs" '
    FILENAME==ours_file { ours[++no]=$0; ours_seen[$0]=1; k=keyof($0); if (k!="") okey[k]=1; next }
    FILENAME==base_file { base[++nb]=$0; base_seen[$0]=1; k=keyof($0); if (k!="") bkey[k]=$0; next }
    FILENAME==theirs_file { theirs[++nt]=$0; theirs_seen[$0]=1; next }
    END {
      for (i=1;i<=nb;i++) {
        line=base[i]
        if (line in ours_seen) continue
        deleted_seen[line]=1
        k=keyof(line)
        if (k!="") deleted_keys[k]=1
      }
      for (i=1;i<=nt;i++) {
        line=theirs[i]
        k=keyof(line)
        if (k!="") tkey[k]=line
      }
      na=0
      for (i=1;i<=nt;i++) {
        line=theirs[i]
        if (line in base_seen) continue
        if (line in ours_seen) continue
        if (line in deleted_seen) continue
        k=keyof(line)
        if (k!="") {
          if (k in okey) continue
          if (k in deleted_keys) continue
        }
        if (line in add_seen) continue
        add[++na]=line
        add_seen[line]=1
      }
      all_pkg=1
      for (j=1;j<=na;j++) if (add[j] !~ /^[[:space:]]*"/) all_pkg=0
      insert_after=0
      insert_before=0
      if (na>0) {
        if (all_pkg) {
          for (i=1;i<=no;i++) if (ours[i] ~ /^[[:space:]]*"/) insert_after=i
        }
        if (insert_after==0) {
          for (i=1;i<=no;i++) if (ours[i] ~ /^[[:space:]]*[]}]/) insert_before=i
        }
      }
      for (i=1;i<=no;i++) {
        if (insert_before==i) for (j=1;j<=na;j++) print add[j]
        line=ours[i]
        k=keyof(line)
        if (k!="" && (k in tkey) && (!(k in bkey) || tkey[k] != bkey[k])) line=tkey[k]
        print line
        if (insert_after==i) for (j=1;j<=na;j++) print add[j]
      }
      if (na>0 && insert_after==0 && insert_before==0) for (j=1;j<=na;j++) print add[j]
    }
    function keyof(line, k) {
      if (match(line, /^[[:space:]]*[^=[:space:]"]+[[:space:]]*=/)) {
        k=line
        sub(/[[:space:]]*=.*/, "", k)
        gsub(/^[[:space:]]+/, "", k)
        return k
      }
      if (match(line, /^[[:space:]]*"[^"]+"/)) {
        k=line
        sub(/^[[:space:]]*"/, "", k)
        sub(/[ "].*/, "", k)
        return k
      }
      return ""
    }
  ' "$ours" "$base" "$theirs" > "$f"
  rm -f "$ours" "$base" "$theirs"
done
git add -A
git commit --no-edit
